CREATE OR REPLACE FUNCTION better_supabase.enroll(tenant uuid, program text, subject_type text, subject_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare
  v_program "better_supabase"."enrollment_programs";
  v_row "better_supabase"."enrollments";
  v_id uuid;
  v_steps text[];
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (enroll.tenant is not null and coalesce(better_supabase.can('tenant', enroll.tenant, 'enrollments.enroll'), false))) then
    raise exception 'not allowed to enroll' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  select * into v_program from "better_supabase"."enrollment_programs" x
  where x."tenant_id" = enroll.tenant and x."key" = enroll.program;
  if v_program."id" is null then
    raise exception 'enrollment program not found' using errcode = 'P0002', hint = 'ENROLLMENTS_PROGRAM_NOT_FOUND';
  end if;
  if not v_program."enabled" then
    raise exception 'this program is turned off' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if enroll.subject_type is null or enroll.subject_type !~ '^[a-z][a-z0-9_-]{0,62}$' or enroll.subject_id is null or length(enroll.subject_id) not between 1 and 200 then
    raise exception 'an enrollment needs a subject type and id' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if cardinality(v_program."subject_types") > 0 and not (enroll.subject_type = any(v_program."subject_types")) then
    raise exception 'this program doesn''t enroll this subject type' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if enroll.subject_type = 'user' and enroll.subject_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'a user subject needs a user id' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  v_steps := array(select t.value ->> 'id' from jsonb_array_elements(v_program."steps") with ordinality as t(value, ord) order by t.ord);
  select * into v_row from "better_supabase"."enrollments" x
  where x."tenant_id" = enroll.tenant and x."program" = enroll.program
    and x."subject_type" = enroll.subject_type and x."subject_id" = enroll.subject_id
  for update;
  if v_row."status" = 'cancelled' then
    update "better_supabase"."enrollments" x
    set "status" = 'active', "cancelled_at" = null, "enrolled_by" = auth.uid(), "enrolled_at" = now(),
      "steps" = v_steps, "program_version" = v_program."version"
    where x."id" = v_row."id";
    update "better_supabase"."enrollments" x
  set "completed_steps" = (select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null),
    "status" = case when x."status" = 'cancelled' then 'cancelled' when ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then 'completed' else 'active' end,
    "completed_at" = case when x."status" <> 'cancelled' and ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then coalesce(x."completed_at", now()) end,
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
    v_id := v_row."id";
  else
    v_id := "better_supabase"."enrollment_ensure"(enroll.tenant, enroll.program, v_program."version", v_steps, enroll.subject_type, enroll.subject_id, auth.uid());
  end if;
  perform "better_supabase"."enrollment_schedule"(v_id);
  return "better_supabase"."enrollment_json"(v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_ensure(tenant uuid, program text, program_version integer, steps text[], subject_type text, subject_id text, actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
begin
  select * into v_row from "better_supabase"."enrollments" x
  where x."tenant_id" is not distinct from enrollment_ensure.tenant and x."program" = enrollment_ensure.program
    and x."subject_type" = enrollment_ensure.subject_type and x."subject_id" = enrollment_ensure.subject_id
  for update;
  if v_row."id" is null then
    insert into "better_supabase"."enrollments" ("tenant_id", "program", "program_version", "subject_type", "subject_id", "user_id", "steps", "enrolled_by")
    values (enrollment_ensure.tenant, enrollment_ensure.program, enrollment_ensure.program_version, enrollment_ensure.subject_type, enrollment_ensure.subject_id, case when enrollment_ensure.subject_type = 'user' then enrollment_ensure.subject_id::uuid end, enrollment_ensure.steps, enrollment_ensure.actor)
    on conflict do nothing
    returning * into v_row;
    if v_row."id" is null then
      select * into v_row from "better_supabase"."enrollments" x
      where x."tenant_id" is not distinct from enrollment_ensure.tenant and x."program" = enrollment_ensure.program
        and x."subject_type" = enrollment_ensure.subject_type and x."subject_id" = enrollment_ensure.subject_id;
      return v_row."id";
    end if;
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
    return v_row."id";
  end if;
  if v_row."steps" is distinct from enrollment_ensure.steps or v_row."program_version" is distinct from enrollment_ensure.program_version then
    update "better_supabase"."enrollments" x set "steps" = enrollment_ensure.steps, "program_version" = enrollment_ensure.program_version
    where x."id" = v_row."id";
    update "better_supabase"."enrollments" x
  set "completed_steps" = (select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null),
    "status" = case when x."status" = 'cancelled' then 'cancelled' when ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then 'completed' else 'active' end,
    "completed_at" = case when x."status" <> 'cancelled' and ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then coalesce(x."completed_at", now()) end,
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  end if;
  return v_row."id";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_json(enrollment_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'id', x."id", 'organizationId', x."tenant_id", 'program', x."program", 'programVersion', x."program_version",
    'subjectType', x."subject_type", 'subjectId', x."subject_id", 'status', x."status",
    'steps', to_jsonb(x."steps"), 'completedSteps', x."completed_steps", 'totalSteps', cardinality(x."steps"),
    'enrolledBy', x."enrolled_by", 'enrolledAt', x."enrolled_at", 'completedAt', x."completed_at",
    'cancelledAt', x."cancelled_at", 'updatedAt', x."updated_at",
    'progress', coalesce((
      select jsonb_agg(jsonb_build_object('step', y."step", 'completedAt', y."completed_at", 'completedBy', y."completed_by") order by y."completed_at", array_position(x."steps", y."step"), y."step")
      from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."completed_at" is not null
    ), '[]'::jsonb),
    'startsAt', x."starts_at", 'endsAt', x."ends_at",
    'schedule', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('step', y."step", 'assignee', case when y."assignee_role" is not null then jsonb_build_object('role', y."assignee_role") when y."assignee_user_id" is not null then jsonb_build_object('userId', y."assignee_user_id") end, 'dueAt', y."due_at", 'completedAt', y."completed_at")) order by array_position(x."steps", y."step"), y."step")
      from "better_supabase"."enrollment_steps" y
      where y."enrollment_id" = x."id"
        and (y."assignee_role" is not null or y."assignee_user_id" is not null or y."due_at" is not null)
    ), '[]'::jsonb)
  )
  from "better_supabase"."enrollments" x
  where x."id" = enrollment_json.enrollment_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_mark(enrollment_id uuid, step text, done boolean, actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
  v_was text;
  v_count integer;
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_mark.enrollment_id for update;
  if v_row."id" is null then
    raise exception 'enrollment not found' using errcode = 'P0002', hint = 'ENROLLMENTS_NOT_FOUND';
  end if;
  if enrollment_mark.step is null or not (enrollment_mark.step = any(v_row."steps")) then
    raise exception 'this step is not part of the program' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if v_row."status" = 'cancelled' then
    raise exception 'the enrollment is cancelled' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  v_was := v_row."status";
  -- An open row of a step with a schedule is completed in place.
  if enrollment_mark.done then
    update "better_supabase"."enrollment_steps" y
    set "completed_by" = enrollment_mark.actor, "completed_at" = now()
    where y."enrollment_id" = v_row."id" and y."step" = enrollment_mark.step and y."completed_at" is null;
    get diagnostics v_count = row_count;
    if v_count = 0 then
      insert into "better_supabase"."enrollment_steps" ("enrollment_id", "tenant_id", "step", "completed_by", "completed_at")
      values (v_row."id", v_row."tenant_id", enrollment_mark.step, enrollment_mark.actor, now())
      on conflict do nothing;
      get diagnostics v_count = row_count;
    end if;
  else
    delete from "better_supabase"."enrollment_steps" x
    where x."enrollment_id" = v_row."id" and x."step" = enrollment_mark.step and x."completed_at" is not null;
    get diagnostics v_count = row_count;
  end if;
  if v_count = 0 then
    return false;
  end if;
  -- A reset step with a schedule gets its open row back.
  if not enrollment_mark.done then
    perform "better_supabase"."enrollment_schedule"(v_row."id");
  end if;
  update "better_supabase"."enrollments" x
  set "completed_steps" = (select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null),
    "status" = case when x."status" = 'cancelled' then 'cancelled' when ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then 'completed' else 'active' end,
    "completed_at" = case when x."status" <> 'cancelled' and ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then coalesce(x."completed_at", now()) end,
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  if enrollment_mark.done then
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.step_completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', enrollment_mark.step, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
    if v_was <> 'completed' and v_row."status" = 'completed' then
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
      null;
    end if;
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_schedule(target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
  v_program "better_supabase"."enrollment_programs";
  v_plan jsonb;
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_schedule.target;
  if v_row."id" is null or v_row."tenant_id" is null then
    return;
  end if;
  select * into v_program from "better_supabase"."enrollment_programs" x
  where x."tenant_id" = v_row."tenant_id" and x."key" = v_row."program";
  v_plan := coalesce((
    select jsonb_agg(jsonb_build_object(
      'step', t.value ->> 'id',
      'role', t.value -> 'assignee' ->> 'role',
      'userId', t.value -> 'assignee' ->> 'userId',
      'dueAt', case t.value -> 'due' ->> 'from'
        when 'start' then coalesce(v_row."starts_at", v_row."enrolled_at") + make_interval(days => (t.value -> 'due' ->> 'days')::integer)
        when 'end' then v_row."ends_at" + make_interval(days => (t.value -> 'due' ->> 'days')::integer)
      end
    ))
    from jsonb_array_elements(coalesce(v_program."steps", '[]'::jsonb)) as t(value)
    where t.value ->> 'id' = any(v_row."steps")
      and (jsonb_typeof(t.value -> 'assignee') = 'object' or jsonb_typeof(t.value -> 'due') = 'object')
  ), '[]'::jsonb);
  delete from "better_supabase"."enrollment_steps" y
  where y."enrollment_id" = v_row."id" and y."completed_at" is null and not exists (select 1 from jsonb_array_elements(v_plan) as z(value) where z.value ->> 'step' = y."step");
  update "better_supabase"."enrollment_steps" y
  set "assignee_role" = null, "assignee_user_id" = null, "due_at" = null
  where y."enrollment_id" = v_row."id" and not exists (select 1 from jsonb_array_elements(v_plan) as z(value) where z.value ->> 'step' = y."step")
    and (y."assignee_role" is not null or y."assignee_user_id" is not null or y."due_at" is not null);
  insert into "better_supabase"."enrollment_steps" as y ("enrollment_id", "tenant_id", "step", "assignee_role", "assignee_user_id", "due_at", "completed_by", "completed_at")
  select v_row."id", v_row."tenant_id", z.value ->> 'step', z.value ->> 'role', (z.value ->> 'userId')::uuid, (z.value ->> 'dueAt')::timestamptz, null, null
  from jsonb_array_elements(v_plan) as z(value)
  on conflict ("enrollment_id", "step") do update
  set "assignee_role" = excluded."assignee_role", "assignee_user_id" = excluded."assignee_user_id", "due_at" = excluded."due_at";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_step(enrollment_id uuid, step text, done boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row "better_supabase"."enrollments";
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_step.enrollment_id;
  if v_row."id" is null or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'enrollments.read'), false))) or (v_row."user_id" is not null and coalesce(v_row."user_id" = auth.uid(), false)) or exists (select 1 from "better_supabase"."enrollment_steps" a where a."enrollment_id" = v_row."id" and a."step" = enrollment_step.step and a."assignee_user_id" = auth.uid())) then
    raise exception 'enrollment not found' using errcode = 'P0002', hint = 'ENROLLMENTS_NOT_FOUND';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'enrollments.enroll'), false))) or (v_row."user_id" is not null and coalesce(v_row."user_id" = auth.uid(), false)) or exists (select 1 from "better_supabase"."enrollment_steps" a where a."enrollment_id" = v_row."id" and a."step" = enrollment_step.step and a."assignee_user_id" = auth.uid())) then
    raise exception 'not allowed to change this enrollment' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  -- A course's steps follow its lessons, so they change only through courses.
  if v_row."program" like 'course:%' then
    raise exception 'this enrollment belongs to a course; complete its lessons through courses' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  -- A sequence's steps run on its schedule, so only its runner marks them.
  if v_row."program" like 'sequence:%' then
    raise exception 'this enrollment belongs to a sequence; its steps run on the sequence''s schedule' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  perform "better_supabase"."enrollment_mark"(v_row."id", enrollment_step.step, enrollment_step.done, auth.uid());
  return "better_supabase"."enrollment_json"(v_row."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.open_enrollment_steps(tenant uuid, assignee_role text DEFAULT NULL::text, assignee_user uuid DEFAULT NULL::uuid, due_before timestamp with time zone DEFAULT NULL::timestamp with time zone, page_size integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_read boolean := (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (open_enrollment_steps.tenant is not null and coalesce(better_supabase.can('tenant', open_enrollment_steps.tenant, 'enrollments.read'), false)));
begin
  if not v_read and auth.uid() is null then
    raise exception 'not allowed to read enrollments' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', o.row_id, 'organizationId', o.scope_id, 'program', o.program,
      'subjectType', o.subject_type, 'subjectId', o.subject_id, 'step', o.step, 'title', o.title,
      'assignee', o.assignee, 'dueAt', o.due_at
    )) order by o.due_at nulls last, o.row_id, o.step)
    from (
      select x."id" as row_id, x."tenant_id" as scope_id, x."program" as program,
        x."subject_type" as subject_type, x."subject_id" as subject_id, y."step" as step,
        case when y."assignee_role" is not null then jsonb_build_object('role', y."assignee_role") when y."assignee_user_id" is not null then jsonb_build_object('userId', y."assignee_user_id") end as assignee, y."due_at" as due_at,
        (select t.value ->> 'title' from "better_supabase"."enrollment_programs" q, jsonb_array_elements(q."steps") as t(value)
          where q."tenant_id" = x."tenant_id" and q."key" = x."program" and t.value ->> 'id' = y."step" limit 1) as title
      from "better_supabase"."enrollment_steps" y
      join "better_supabase"."enrollments" x on x."id" = y."enrollment_id"
      where y."tenant_id" = open_enrollment_steps.tenant and x."tenant_id" = open_enrollment_steps.tenant
        and y."completed_at" is null and x."status" = 'active'
        and (v_read or y."assignee_user_id" = auth.uid())
        and (open_enrollment_steps.assignee_role is null or y."assignee_role" = open_enrollment_steps.assignee_role)
        and (open_enrollment_steps.assignee_user is null or y."assignee_user_id" = open_enrollment_steps.assignee_user)
        and (open_enrollment_steps.due_before is null or y."due_at" < open_enrollment_steps.due_before)
      order by y."due_at" nulls last, x."id", y."step"
      limit least(greatest(coalesce(open_enrollment_steps.page_size, 50), 1), 200)
    ) o
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_enrollment_program(tenant uuid, program jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare
  v_id uuid;
  v_old "better_supabase"."enrollment_programs";
  v_row "better_supabase"."enrollment_programs";
  v_key text;
  v_name text;
  v_description text;
  v_types text[];
  v_steps jsonb;
  v_enabled boolean;
  v_step jsonb;
  v_ids text[] := '{}';
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (save_enrollment_program.tenant is not null and coalesce(better_supabase.can('tenant', save_enrollment_program.tenant, 'enrollments.manage'), false))) then
    raise exception 'not allowed to manage enrollment programs' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  if save_enrollment_program.program is null or jsonb_typeof(save_enrollment_program.program) <> 'object' then
    raise exception 'program must be an object' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  v_id := nullif(save_enrollment_program.program ->> 'id', '')::uuid;
  if v_id is not null then
    select * into v_old from "better_supabase"."enrollment_programs" x
    where x."id" = v_id and x."tenant_id" = save_enrollment_program.tenant
    for update;
    if v_old."id" is null then
      raise exception 'enrollment program not found' using errcode = 'P0002', hint = 'ENROLLMENTS_PROGRAM_NOT_FOUND';
    end if;
    if save_enrollment_program.program ? 'version' and (save_enrollment_program.program ->> 'version')::integer is distinct from v_old."version" then
      raise exception 'the program changed since you read it' using errcode = '40001', hint = 'ENROLLMENTS_PROGRAM_CONFLICT';
    end if;
  end if;
  if save_enrollment_program.program ? 'subjectTypes' and jsonb_typeof(save_enrollment_program.program -> 'subjectTypes') <> 'array' then
    raise exception 'subjectTypes must be an array of subject types' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  v_key := coalesce(save_enrollment_program.program ->> 'key', v_old."key");
  v_name := trim(coalesce(save_enrollment_program.program ->> 'name', v_old."name"));
  v_description := case when save_enrollment_program.program ? 'description'
    then nullif(trim(save_enrollment_program.program ->> 'description'), '') else v_old."description" end;
  v_types := case when save_enrollment_program.program ? 'subjectTypes'
    then array(select t.value from jsonb_array_elements_text(save_enrollment_program.program -> 'subjectTypes') with ordinality as t(value, ord) order by t.ord)
    else coalesce(v_old."subject_types", '{}') end;
  v_steps := case when save_enrollment_program.program ? 'steps'
    then save_enrollment_program.program -> 'steps' else coalesce(v_old."steps", '[]'::jsonb) end;
  v_enabled := case when save_enrollment_program.program ? 'enabled'
    then (save_enrollment_program.program ->> 'enabled')::boolean else coalesce(v_old."enabled", true) end;
  if v_key is null or v_key !~ '^[a-z][a-z0-9_-]{0,62}$' then
    raise exception 'key: use lowercase letters, digits, "_" or "-", starting with a letter' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if v_old."id" is not null and v_key <> v_old."key" then
    raise exception 'a program''s key can''t change' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if v_name is null or length(v_name) not between 1 and 200 then
    raise exception 'name must be 1 to 200 characters' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if length(v_description) > 2000 then
    raise exception 'description must be at most 2000 characters' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if exists (select 1 from unnest(v_types) as t(value) where t.value is null or t.value !~ '^[a-z][a-z0-9_-]{0,62}$') then
    raise exception 'subjectTypes must be lower-case subject types' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if jsonb_typeof(v_steps) <> 'array' or jsonb_array_length(v_steps) = 0 then
    raise exception 'steps: pass at least one step' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if jsonb_array_length(v_steps) > 100 then
    raise exception 'a program holds at most 100 steps' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  for v_step in select t.value from jsonb_array_elements(v_steps) as t(value) loop
    if jsonb_typeof(v_step) <> 'object' or coalesce(v_step ->> 'id', '') !~ '^[a-z][a-z0-9_.-]{0,63}$' then
      raise exception 'each step needs an id of lowercase letters, digits, "_", "." or "-"' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
    end if;
    if (v_step ->> 'id') = any(v_ids) then
      raise exception 'step ids must be unique' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
    end if;
    if length(v_step ->> 'title') > 200 or length(v_step ->> 'description') > 2000 then
      raise exception 'a step title holds at most 200 characters and a description 2000' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
    end if;
    if jsonb_typeof(v_step -> 'assignee') is not null and jsonb_typeof(v_step -> 'assignee') <> 'null' then
      if jsonb_typeof(v_step -> 'assignee') <> 'object' then
        raise exception 'a step assignee is { role } with a lowercase role or { userId } with a user id' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
      end if;
      if (select count(*) from jsonb_object_keys(v_step -> 'assignee')) <> 1
        or not (coalesce(v_step -> 'assignee' ->> 'role', '') ~ '^[a-z][a-z0-9_-]{0,62}$' or coalesce(v_step -> 'assignee' ->> 'userId', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
        raise exception 'a step assignee is { role } with a lowercase role or { userId } with a user id' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
      end if;
    end if;
    if jsonb_typeof(v_step -> 'due') is not null and jsonb_typeof(v_step -> 'due') <> 'null' then
      if jsonb_typeof(v_step -> 'due') <> 'object' then
        raise exception 'a step due date is { days, from } with whole days from -3650 to 3650 and from "start" or "end"' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
      end if;
      if exists (select 1 from jsonb_object_keys(v_step -> 'due') as k(key) where k.key not in ('days', 'from'))
        or coalesce(v_step -> 'due' ->> 'from', '') not in ('start', 'end')
        or jsonb_typeof(v_step -> 'due' -> 'days') is distinct from 'number'
        or (case when (v_step -> 'due' ->> 'days') ~ '^-?[0-9]{1,4}$' then abs((v_step -> 'due' ->> 'days')::integer) > 3650 else true end) then
        raise exception 'a step due date is { days, from } with whole days from -3650 to 3650 and from "start" or "end"' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
      end if;
    end if;
    v_ids := v_ids || (v_step ->> 'id');
  end loop;
  v_steps := (
    select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', t.value ->> 'id', 'title', t.value ->> 'title', 'description', t.value ->> 'description',
      'assignee', case when jsonb_typeof(t.value -> 'assignee') = 'object' then t.value -> 'assignee' end,
      'due', case when jsonb_typeof(t.value -> 'due') = 'object' then jsonb_build_object('days', (t.value -> 'due' ->> 'days')::integer, 'from', t.value -> 'due' ->> 'from') end)) order by t.ord)
    from jsonb_array_elements(v_steps) with ordinality as t(value, ord)
  );
  if v_old."id" is null then
    insert into "better_supabase"."enrollment_programs" ("tenant_id", "key", "name", "description", "subject_types", "steps", "enabled", "created_by")
    values (save_enrollment_program.tenant, v_key, v_name, v_description, v_types, v_steps, v_enabled, auth.uid())
    on conflict ("tenant_id", "key") do nothing
    returning * into v_row;
    if v_row."id" is null then
      raise exception 'a program with this key already exists' using errcode = '23505', hint = 'ENROLLMENTS_PROGRAM_EXISTS';
    end if;
  else
    update "better_supabase"."enrollment_programs" x
    set "name" = v_name, "description" = v_description, "subject_types" = v_types, "steps" = v_steps,
      "enabled" = v_enabled,
      "version" = x."version" + case when x."steps" is distinct from v_steps then 1 else 0 end,
      "updated_at" = now()
    where x."id" = v_old."id"
    returning * into v_row;
  end if;
  perform "better_supabase".emit_event('enrollment_program.saved', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'key', v_row."key", 'version', v_row."version"), 'enrollment-programs/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  perform better_supabase.audit_event(
    event_type => 'enrollment_program.saved',
    category => 'data',
    target_type => 'enrollment_program',
    record_id => v_row."id"::text,
    target_label => v_row."name",
    summary => 'saved an enrollment program',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'key', v_row."key", 'version', v_row."version")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'key', v_row."key", 'name', v_row."name", 'description', v_row."description", 'subjectTypes', to_jsonb(v_row."subject_types"), 'steps', v_row."steps", 'enabled', v_row."enabled", 'version', v_row."version", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.set_enrollment_dates(enrollment_id uuid, dates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
  v_starts timestamptz;
  v_ends timestamptz;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."enrollments" x where x."id" = set_enrollment_dates.enrollment_id for update;
  if v_row."id" is null or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'enrollments.read'), false))) then
    raise exception 'enrollment not found' using errcode = 'P0002', hint = 'ENROLLMENTS_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'enrollments.enroll'), false))) then
    raise exception 'not allowed to change this enrollment' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  if position(':' in v_row."program") > 0 then
    raise exception 'this enrollment belongs to a module and has no schedule' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if dates is null or jsonb_typeof(dates) <> 'object' then
    raise exception 'dates must be an object' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  v_starts := v_row."starts_at";
  v_ends := v_row."ends_at";
  if dates ? 'startsAt' then
    begin
      v_starts := (dates ->> 'startsAt')::timestamptz;
    exception when invalid_datetime_format or datetime_field_overflow or invalid_text_representation then
      raise exception 'startsAt must be an ISO 8601 instant or null' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
    end;
  end if;
  if dates ? 'endsAt' then
    begin
      v_ends := (dates ->> 'endsAt')::timestamptz;
    exception when invalid_datetime_format or datetime_field_overflow or invalid_text_representation then
      raise exception 'endsAt must be an ISO 8601 instant or null' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
    end;
  end if;
  if v_ends < v_starts then
    raise exception 'endsAt can''t be before startsAt' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  update "better_supabase"."enrollments" x
  set "starts_at" = v_starts, "ends_at" = v_ends, "updated_at" = now()
  where x."id" = v_row."id";
  perform "better_supabase"."enrollment_schedule"(v_row."id");
  return "better_supabase"."enrollment_json"(v_row."id");
end;
$function$;

CREATE OR REPLACE FUNCTION api.open_enrollment_steps(tenant uuid, assignee_role text DEFAULT NULL::text, assignee_user uuid DEFAULT NULL::uuid, due_before timestamp with time zone DEFAULT NULL::timestamp with time zone, page_size integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select "better_supabase"."open_enrollment_steps"($1, $2, $3, $4, $5) $function$;

CREATE OR REPLACE FUNCTION api.set_enrollment_dates(enrollment_id uuid, dates jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select "better_supabase"."set_enrollment_dates"($1, $2) $function$;

ALTER TABLE "better_supabase"."enrollment_steps" ADD CONSTRAINT "enrollment_steps_assignee_role_check" CHECK (((assignee_role IS NULL) OR (assignee_role ~ '^[a-z][a-z0-9_-]{0,62}$'::text)));

ALTER TABLE "better_supabase"."enrollment_steps" ADD CONSTRAINT "enrollment_steps_assignee_user_id_fkey" FOREIGN KEY (assignee_user_id) REFERENCES auth.users(id) ON DELETE SET NULL;

CREATE INDEX enrollment_steps_assignee_idx ON better_supabase.enrollment_steps USING btree (assignee_user_id, due_at);

CREATE INDEX enrollment_steps_due_idx ON better_supabase.enrollment_steps USING btree (tenant_id, due_at) WHERE (completed_at IS NULL);

REVOKE ALL ON FUNCTION "api"."open_enrollment_steps"(uuid, text, uuid, timestamp with time zone, integer) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "api"."open_enrollment_steps"(uuid, text, uuid, timestamp with time zone, integer) TO "authenticated", "service_role";

REVOKE ALL ON FUNCTION "api"."set_enrollment_dates"(uuid, jsonb) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "api"."set_enrollment_dates"(uuid, jsonb) TO "authenticated", "service_role";

REVOKE ALL ON FUNCTION "better_supabase"."enrollment_schedule"(uuid) FROM PUBLIC;

REVOKE ALL ON FUNCTION "better_supabase"."open_enrollment_steps"(uuid, text, uuid, timestamp with time zone, integer) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "better_supabase"."open_enrollment_steps"(uuid, text, uuid, timestamp with time zone, integer) TO "authenticated", "service_role";

REVOKE ALL ON FUNCTION "better_supabase"."set_enrollment_dates"(uuid, jsonb) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION "better_supabase"."set_enrollment_dates"(uuid, jsonb) TO "authenticated", "service_role";
